package com.example.data.local

object BedtimeSunnahData {

    fun getBedtimeSunnahDuas(): List<DuaEntity> {
        return listOf(
            // 1. Sunnoni da Hanyoyin Kwanciya Barci na Manzon Allah (ﷺ)
            DuaEntity(
                id = 360,
                category = "Bedtime & Night Sunnah",
                title = "Ibadu da Hanyoyin Sunnah Kafin Kwanciya Barci (The Prophetic Bedtime Sunnah Routine)",
                arabic = "قَالَ رَسُولُ اللَّهِ ﷺ: «إِذَا أَتَيْتَ مَضْجَعَكَ فَتَوَضَّأْ وُضُوءَكَ لِلصَّلَاةِ، ثُمَّ اضْطَجِعْ عَلَى شِقِّكَ الأَيْمَنِ...» وَقَالَ ﷺ: «إِذَا جَاءَ أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْهُ بِدَاخِلَةِ إِزَارِهِ ثَلَاثَ مَرَّاتٍ فَإِنَّهُ لَا يَدْرِي مَا خَلَفَهُ عَلَيْهِ»",
                transliteration = "Qala Rasulullahi (SAW): 'Idha atayta madhja'aka fa-tawadda' wudu'aka lis-salah, thumma-d-taji' 'ala shiqqikal-ayman...' Wa qala (SAW): 'Idha ja'a ahadukum ila firashihi fal-yanfud-hu bi-dakhilati izarihi thalatha marrat fa-innahu la yadri ma khalafahu 'alayh.'",
                translation = "The Prophet (ﷺ) said: 'When you go to bed, perform ablution as you do for prayer, then lie down on your right side...' And he said: 'When one of you goes to his bed, he should dust it with the inside of his garment three times, for he does not know what came upon it after him.'",
                translationHausa = "Cikakkun Hanyoyin Sunnah Kafin Kwanciya Barci:\n" +
                        "1. Yin alwala cikakkiya kamar alwalar sallah kafin kwanciya.\n" +
                        "2. Kakkabe shimfida sau uku (3) da gefen mayafi ko tufafi tare da ambaton Bismillah.\n" +
                        "3. Kwanciya a gefen dama da sanya tafin hannun dama a karkashin kuncin dama.\n" +
                        "4. Kauce wa kwanciya rub-da-ciki (a kan ciki) domin kwanciya ce da Allah ba Ya so.\n" +
                        "5. Kashe wuta, kyandir ko fitilu, da rufe tasoshin abinci da na ruwa tare da kiran sunan Allah.\n" +
                        "6. Karanta cikakkiyar Suratul Mulk da Suratus-Sajdah.\n" +
                        "7. Karanta Ayat al-Kursi da ayoyi biyu na karshen Suratul Baqarah.\n" +
                        "8. Hada tafukan hannaye a karanta Kulhuwa, Falaqi da Nasi sannan a tofa a shafi dukkan jiki sau 3.\n" +
                        "9. Yin Tasbihin Sayyidatina Fatima (Subhanallah 33, Alhamdulillah 33, Allahu Akbar 34) wanda ya cika tasbihi 100.\n" +
                        "10. Fadin addu'ar 'Bismika Rabbi' da kuma 'Allahumma aslamtu nafsi ilayk' a matsayin magana ta karshe kafin barci.",
                translationYoruba = "Àwọn Ìṣe Sunnah Ṣáájú Sísùn: Ṣe àlwálà gẹ́gẹ́ bí ti sọláàti, gbọn ibùsùn rẹ ní ẹ̀mẹ́ta, sùn sí apá ọ̀tún rẹ pẹ̀lú ọwọ́ ọ̀tún lábẹ́ ẹ̀rẹ̀kẹ́, ka Kúlhuwa, Fálakì ati Nási ní ẹ̀mẹ́ta, ka Ayat al-Kursi, Suratul Mulk ati tasbihi 100.",
                translationIgbo = "Omume Sunnah Tupu Ụra: Mee alwala dịka ị na-eme maka ekpere, kpochapụ ihe ndina gị ugboro 3, dina n'akụkụ aka nri gị na aka nri n'okpuru nti gị, gụọ Suratul Mulk, Ayat al-Kursi, na tasbeeh 100.",
                reference = "Sahih Al-Bukhari no. 247, 6320; Sahih Muslim no. 2710, 2714; Riyadus-Salihin no. 1457."
            ),

            // 2. Cikakkiyar Suratul Mulk (Full Surah Al-Mulk - Verses 1 to 30)
            DuaEntity(
                id = 361,
                category = "Bedtime & Night Sunnah",
                title = "Cikakkiyar Suratul Mulk (Full Surah Al-Mulk - Ayoyi 1-30)",
                arabic = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\n\n" +
                        "﴿١﴾ تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ\n" +
                        "﴿٢﴾ الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ الْعَزِيزُ الْغَفُورُ\n" +
                        "﴿٣﴾ الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِي خَلْقِ الرَّحْمَٰنِ مِن تَفَاوُتٍ ۖ فَارْجِعِ الْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ\n" +
                        "﴿٤﴾ ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ الْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ\n" +
                        "﴿٥﴾ وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَجَعَلْنَاهَا رُجُومًا لِّلشَّيَاطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيرِ\n" +
                        "﴿٦﴾ وَلِلَّذِينَ كَفَرُوا بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ الْمَصِيرُ\n" +
                        "﴿٧﴾ إِذَا أُلْقُوا فِيهَا سَمِعُوا لَهَا شَهِيقًا وَهِيَ تَفُورُ\n" +
                        "﴿٨﴾ تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِ ۖ كُلَّمَا أُلْقِيَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ نَذِيرٌ\n" +
                        "﴿٩﴾ قَالُوا بَلَىٰ قَدْ جَاءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اللَّهُ مِن شَيْءٍ إِنْ أَنتُمْ إِلَّا فِي ضَلَالٍ كَبِيرٍ\n" +
                        "﴿١٠﴾ وَقَالُوا لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِي أَصْحَابِ السَّعِيرِ\n" +
                        "﴿١١﴾ فَاعْتَرَفُوا بِذَنبِهِمْ فَسُحْقًا لِّأَصْحَابِ السَّعِيرِ\n" +
                        "﴿١٢﴾ إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُم بِالْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ\n" +
                        "﴿١٣﴾ وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهَرُوا بِهِ ۖ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ\n" +
                        "﴿١٤﴾ أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ\n" +
                        "﴿١٥﴾ هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِن رِّزْقِهِ ۖ وَإِلَيْهِ النُّشُورُ\n" +
                        "﴿١٦﴾ أَأَمِنتُم مَّن فِي السَّمَاءِ أَن يَخْسِفَ بِكُمُ الْأَرْضَ فَإِذَا هِيَ تَمُورُ\n" +
                        "﴿١٧﴾ أَمْ أَمِنتُم مَّن فِي السَّمَاءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ\n" +
                        "﴿١٨﴾ وَلَقَدْ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ\n" +
                        "﴿١٩﴾ أَوَلَمْ يَرَوْا إِلَى الطَّيْرِ فَوْقَهُمْ صَافَّاتٍ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا الرَّحْمَٰنُ ۚ إِنَّهُ بِكُلِّ شَيْءٍ بَصِيرٌ\n" +
                        "﴿٢٠﴾ أَمَّنْ هَٰذَا الَّذِي هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ الرَّحْمَٰنِ ۚ إِنِ الْكَافِرُونَ إِلَّا فِي غُرُورٍ\n" +
                        "﴿٢١﴾ أَمَّنْ هَٰذَا الَّذِي يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُ ۚ بَل لَّجُّوا فِي عُتُوٍّ وَنُفُورٍ\n" +
                        "﴿٢٢﴾ أَفَمَن يَمْشِي مُكِبًّا عَلَىٰ وَجْهِهِ أَهْدَىٰ أَمَّن يَمْشِي سَوِيًّا عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ\n" +
                        "﴿٢٣﴾ قُلْ هُوَ الَّذِي أَنشَأَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ ۖ قَلِيلًا مَّا تَشْكُرُونَ\n" +
                        "﴿٢٤﴾ قُلْ هُوَ الَّذِي ذَرَأَكُمْ فِي الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ\n" +
                        "﴿٢٥﴾ وَيَقُولُونَ مَتَىٰ هَٰذَا الْوَعْدُ إِن كُنتُمْ صَادِقِينَ\n" +
                        "﴿٢٦﴾ قُلْ إِنَّمَا الْعِلْمُ عِندَ اللَّهِ وَإِنَّمَا أَنَا نَذِيرٌ مُّبِينٌ\n" +
                        "﴿٢٧﴾ فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا وَقِيلَ هَٰذَا الَّذِي كُنتُم بِهِ تَدَّعُونَ\n" +
                        "﴿٢٨﴾ قُلْ أَرَأَيْتُمْ إِنْ أَهْلَكَنِيَ اللَّهُ وَمَن مَّعِيَ أَوْ رَحِمَنَا فَمَن يُجِيرُ الْكَافِرِينَ مِنْ عَذَابٍ أَلِيمٍ\n" +
                        "﴿٢٩﴾ قُلْ هُوَ الرَّحْمَٰنُ آمَنَّا بِهِ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِي ضَلَالٍ مُّبِينٍ\n" +
                        "﴿٣٠﴾ قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَاءٍ مَّعِينٍ",
                transliteration = "Bismillahir-Rahmanir-Rahim.\n" +
                        "[1] Tabarakalladhi bi-yadihil-mulku wa Huwa 'ala kulli shay'in Qadeer. [2] Alladhi khalaqal-mawta wal-hayata li-yabluwakum ayyukum ahsanu 'amala, wa Huwal-'Azizul-Ghafur. [3] Alladhi khalaqa sab'a samawatin tibaqan, ma tara fi khalqir-Rahmani min tafawut, farji'il-basara hal tara min futur. [4] Thummar-ji'il-basara karratayni yanqalib ilaykal-basaru khasi'an wa huwa haseer. [5] Wa laqad zayyannas-sama'ad-dunya bi-masabiha wa ja'alnaha rujuman lish-shayateeni wa a'tadna lahum 'adhabas-sa'eer. [6] Wa lilladhina kafaru bi-Rabbihim 'adhabu jahannama wa bi'sal-maseer. [7] Idha ulqu feeha sami'u laha shaheeqan wa hiya tafoor. [8] Takadu tamayyazu minal-ghayz, kullama ulqiya feeha fawjun sa'alahum khazanatuha alam ya'tikum nadheer. [9] Qalu bala qad ja'ana nadheerun fa-kadh-dhabna wa qulna ma nazzalallahu min shay'in in antum illa fee dalalin kabeer. [10] Wa qalu law kunna nasma'u aw na'qilu ma kunna fee as-habis-sa'eer. [11] Fa'tarafu bi-dhambihim fa-suhqan li-as-habis-sa'eer. [12] Innalladhina yakhshawna Rabbahum bil-ghaybi lahum maghfiratun wa ajrun kabeer. [13] Wa asirru qawlakum awij-haru bihi, innahu 'Alimun bi-dhatis-sudoor. [14] Ala ya'lamu man khalaqa wa Huwal-Lateeful-Khabeer. [15] Huwalladhi ja'ala lakumul-arda dhalulan famshu fee manakibiha wa kulu mir-rizqihi wa ilayhin-nushoor. [16] A-amintum man fis-sama'i an yakhsifa bikumul-arda fa-idha hiya tamoor. [17] Am amintum man fis-sama'i an yursila 'alaykum hasiban fa-sata'lamuna kayfa nadheer. [18] Wa laqad kadh-dhaballadhina min qablihim fa-kayfa kana nakeer. [19] Awa-lam yaraw ilat-tayri fawqahum saffatin wa yaqbidn, ma yumsikuhunna illar-Rahman, innahu bi-kulli shay'in Baseer. [20] Amman hadhalladhi huwa jundun lakum yansurukum min dunir-Rahman, inil-kafiruna illa fee ghuroor. [21] Amman hadhalladhi yarzuqukum in amsaka rizqahu, bal lajju fee 'utuwwin wa nufoor. [22] Afaman yamshi mukibban 'ala wajhihi ahda amman yamshi sawiyyan 'ala siratim-mustaqeem. [23] Qul Huwalladhi ansha'akum wa ja'ala lakumus-sam'a wal-absara wal-af'idata qalilam-ma tashkuroon. [24] Qul Huwalladhi dhara'akum fil-ardi wa ilayhi tuhsharoon. [25] Wa yaquluna mata hadhal-wa'du in kuntum sadiqeen. [26] Qul innamal-'ilmu 'indallahi wa innama ana nadheerum-mubeen. [27] Falamma ra'awhu zulfatan see'at wujuhulladhina kafaru wa qila hadhalladhi kuntum bihi tadda'oon. [28] Qul ara'aytum in ahlakaniyallahu wa mam-ma'iya aw rahimana faman yujeorul-kafirina min 'adhabin aleem. [29] Qul Huwar-Rahmanu amanna bihi wa 'alayhi tawakkalna, fa-sata'lamuna man huwa fee dalalim-mubeen. [30] Qul ara'aytum in asbaha ma'ukum ghawran faman ya'teekum bi-ma'im-ma'een.",
                translation = "Surah Al-Mulk (The Sovereignty) - Verses 1 to 30:\n" +
                        "[1] Blessed is He in whose hand is dominion, and He is over all things competent.\n" +
                        "[2] [He] who created death and life to test you [as to] which of you is best in deed - and He is the Exalted in Might, the Forgiving.\n" +
                        "[3] [And] who created seven heavens in layers. You do not see in the creation of the Most Merciful any inconsistency. So return [your] vision [to the sky]; do you see any breaks?\n" +
                        "[4] Then return your vision twice again. [Your] vision will return to you humbled while it is fatigued.\n" +
                        "[5] And We have certainly beautified the nearest heaven with stars and have made [from] them missiles for the devils and have prepared for them the punishment of the Blaze.\n" +
                        "[6] And for those who disbelieved in their Lord is the punishment of Hell, and wretched is the destination.\n" +
                        "[7] When they are thrown into it, they hear from it a dreadful inhaling while it boils up.\n" +
                        "[8] It almost bursts with rage. Every time a company is thrown into it, its keepers ask them, 'Did there not come to you a warner?'\n" +
                        "[9] They will say, 'Yes, a warner had come to us, but we denied and said, \"Allah has not sent down anything. You are not but in great error.\"' \n" +
                        "[10] And they will say, 'If only we had been listening or reasoning, we would not be among the companions of the Blaze.'\n" +
                        "[11] And they will admit their sin, so [it is] alienation for the companions of the Blaze.\n" +
                        "[12] Indeed, those who fear their Lord unseen will have forgiveness and great reward.\n" +
                        "[13] And conceal your speech or publicize it; indeed, He is Knowing of that within the breasts.\n" +
                        "[14] Does He who created not know, while He is the Subtle, the Acquainted?\n" +
                        "[15] It is He who made the earth tame for you - so walk among its slopes and eat of His provision - and to Him is the resurrection.\n" +
                        "[16] Do you feel secure that He who [has subtle power] in the heaven would not cause the earth to swallow you and suddenly it would sway?\n" +
                        "[17] Or do you feel secure that He who [has subtle power] in the heaven would not send against you a storm of stones? Then you would know how [terrible] was My warning.\n" +
                        "[18] And already had those before them denied, and how [terrible] was My reproach.\n" +
                        "[19] Do they not see the birds above them with wings outspread and [sometimes] folded in? None holds them [aloft] except the Most Merciful. Indeed He is, of all things, Seeing.\n" +
                        "[20] Or who is it that could be an army for you to aid you other than the Most Merciful? The disbelievers are not but in delusion.\n" +
                        "[21] Or who is it that could provide for you if He withheld His provision? But they have persisted in insolence and aversion.\n" +
                        "[22] Then is one who walks fallen on his face better guided or one who walks erect on a straight path?\n" +
                        "[23] Say, 'It is He who has produced you and made for you hearing and vision and hearts; little are you grateful.'\n" +
                        "[24] Say, 'It is He who has multiplied you throughout the earth, and to Him you will be gathered.'\n" +
                        "[25] And they say, 'When is this promise, if you should be truthful?'\n" +
                        "[26] Say, 'The knowledge is only with Allah, and I am only a clear warner.'\n" +
                        "[27] But when they see it approaching, the faces of those who disbelieve will be distressed, and it will be said, 'This is that for which you used to call.'\n" +
                        "[28] Say, [O Muhammad], 'Have you considered: whether Allah should cause my death and those with me or have mercy upon us, who can protect the disbelievers from a painful punishment?'\n" +
                        "[29] Say, 'He is the Most Merciful; we have believed in Him, and upon Him we have relied. And you will know who it is that is in clear error.'\n" +
                        "[30] Say, 'Have you considered: if your water was to become sunken [into the earth], then who could bring you flowing water?'",
                translationHausa = "Fassarar Cikakkiyar Suratul Mulk (Ayoyi 1 zuwa 30):\n\n" +
                        "[1] Albarka ta tabbata ga Wanda mulki yake a hannunSa, kuma Shi a kan komai Mai ikon yi ne.\n" +
                        "[2] Wanda Ya halicci mutuwa da rayuwa domin Ya jarraba ku, wannenku ne ya fi kyawun aiki. Kuma Shi ne Mabuwayi, Mai yawan gafara.\n" +
                        "[3] Wanda Ya halicci sammai bakwai hawa-hawa. Ba za ka ga wani sabani a cikin halittar Mai Rahama ba. Ka sake mayar da gani: ko ka ga wata kafa ko tsagewa?\n" +
                        "[4] Sa'an nan ka sake mayar da gani sau biyu, ganinka zai dawo gare ka yana mai wulakanta kuma yana mai gajiya.\n" +
                        "[5] Kuma lallai Mun kawata saman duniya da fitilu (taurari), kuma Muka sanya su abin jifa ga shaidanu, kuma Muka tanadar musu azabar Sa'ir.\n" +
                        "[6] Kuma wadanda suka kafirce wa Ubangijinsu suna da azabar Jahannama, kuma makoma ta munana.\n" +
                        "[7] Idan aka jefa su a cikinta, sai su ji wani irin kugi mai ban tsoro yayin da take tafasa.\n" +
                        "[8] Tana kusa ta dare saboda tsananin fushi. Duk lokacin da aka jefa wata tawaga a cikinta, masu tsaronta sai su tambaye su: 'Shin wani mai gargadi bai zo muku ba?'\n" +
                        "[9] Sai su ce: 'Na'am, hakika mai gargadi ya zo mana, sai muka karyata shi kuma muka ce: Allah bai saukar da komai ba; ba ku zama ba face a cikin bata mai girma.'\n" +
                        "[10] Kuma suka ce: 'Da mun kasance muna ji ko muna hankalta, da ba mu kasance a cikin 'yan wutar Sa'ir ba!'\n" +
                        "[11] Sai suka amsa laifinsu; to, tsinuwa ta tabbata ga 'yan wutar Sa'ir!\n" +
                        "[12] Lallai wadanda suke tsoron Ubangijinsu a fake, suna da gafara da lada mai girma.\n" +
                        "[13] Kuma ku asirta maganarku ko ku bayyana ta; lallai Shi Masani ne ga abin da ke cikin zukata.\n" +
                        "[14] Ashe Wanda Ya halitta ba zai sani ba? Alhali Shi ne Mai tausasawa, Masani!\n" +
                        "[15] Shi ne Wanda Ya sanya muku kasa mai saukin zama, sai ku yi tafiya a sassan kwarurukanta, kuma ku ci daga arzikinSa, kuma zuwa gare Shi ne tashi yake.\n" +
                        "[16] Shin kun amince da Wanda ke cikin sama cewa ba zai shafe kasa da ku ba, sai ga ta tana girgiza?\n" +
                        "[17] Ko kun amince da Wanda ke cikin sama cewa ba zai saki guguwar tsakuwa a kanku ba? To za ku san yadda gargadiNa yake!\n" +
                        "[18] Kuma hakika wadanda ke gabaninsu sun karyata; to, yaya musunNa ya kasance?\n" +
                        "[19] Shin ba su duba tsuntsaye a samansu ba, suna shimfida fikafikansu kuma suna ninke su? Babu mai rike su sai Mai Rahama; lallai Shi Mai gani ne ga kowane abu.\n" +
                        "[20] Wane ne wannan da yake runduna a gare ku da zai taimake ku koma bayan Mai Rahama? Kafirai ba su zama ba face a cikin rudu.\n" +
                        "[21] Ko wane ne wannan da zai azurta ku idan Ya rike arzikinSa? A'a, sun zurfafa a cikin girman kai da kiyayya.\n" +
                        "[22] Shin wanda yake tafiya a kife a kan fuskarsa ne ya fi shiryuwa ko kuwa wanda yake tafiya a mike a kan tafarki madaidaici?\n" +
                        "[23] Ka ce: 'Shi ne Wanda Ya kaga halittarku, kuma Ya sanya muku ji da gani da zukata; kadan ne kuke godewa.'\n" +
                        "[24] Ka ce: 'Shi ne Wanda Ya watsa ku a cikin kasa, kuma zuwa gare Shi za a tara ku.'\n" +
                        "[25] Kuma suna cewa: 'Yaushe wannan alkawari zai cika idan kun kasance masu gaskiya?'\n" +
                        "[26] Ka ce: 'Ilimin wannan yana wurin Allah ne kawai, kuma ni mai gargadi ne kawai mai bayyanawa.'\n" +
                        "[27] To, a lokacin da suka gan ta kusa, sai fuskokin wadanda suka kafirta suka munana, kuma aka ce: 'Wannan shi ne abin da kuke kira da gaggawa!'\n" +
                        "[28] Ka ce: 'Shin kun gani, idan Allah Ya halakar da ni da wadanda ke tare da ni, ko Ya yi mana rahama, to wane ne zai tseratar da kafirai daga azaba mai radadi?'\n" +
                        "[29] Ka ce: 'Shi ne Mai Rahama, mun yi imani da Shi, kuma a gare Shi muka dogara; to, za ku san wanda yake a cikin bata bayyananniya.'\n" +
                        "[30] Ka ce: 'Shin kun gani, idan ruwanku ya wayi gari ya kafu a karkashin kasa, to wane ne zai zo muku da ruwa mai bubbugowa?'",
                translationYoruba = "Suratul Mulk (Orí 67 - Ẹsẹ 1 sí 30): Ọlá ati ìbùkún ni fún Ẹni tí ìjọba wà ní ọwọ́ Rẹ̀, Ẹni tí Ó dá ikú àti àyè láti dán yín wò. Kíkà rẹ̀ ṣáájú sísùn jẹ́ ààbò kúrò nínú ìyà ibojì.",
                translationIgbo = "Suratul Mulk (Isi nke 67 - Amaokwu 1 ruo 30): Onye Nwe Eze nke eluigwe na ala. Ọgụgụ ya tupu ụra na-azọpụta mmadụ n'ahụhụ nke ili.",
                reference = "Surah Al-Mulk (Chapter 67: 1-30). Annabi (ﷺ) ya ce: 'Surah ce a cikin Alkur'ani mai ayoyi talatin (30), ta yi ceto ga wani mutum har sai da aka gafarta masa, ita ce Tabarakallazi bi-yadihil Mulk.' Kuma Annabi (ﷺ) ba ya barci har sai ya karanta ta. (Jami' At-Tirmidhi no. 2891, 2892; Abu Dawud no. 1400; Sahih)."
            ),

            // 3. Tasbihi Dari (100 Tasbeeh) na Sayyidatina Fatima (RA)
            DuaEntity(
                id = 362,
                category = "Bedtime & Night Sunnah",
                title = "Tasbihi Dari (100 Tasbeeh) na Sayyidatina Fatima (RA) Kafin Barci",
                arabic = "سُبْحَانَ اللَّهِ (٣٣ مَرَّةً)،\n" +
                        "وَالْحَمْدُ لِلَّهِ (٣٣ مَرَّةً)،\n" +
                        "وَاللَّهُ أَكْبَرُ (٣٤ مَرَّةً)\n\n" +
                        "[الْمَجْمُوعُ: ١٠٠ تَسْبِيحَةٍ عِنْدَ النَّوْمِ]",
                transliteration = "Subhanallah (33 times),\n" +
                        "Wal-Hamdu lillah (33 times),\n" +
                        "Wallahu Akbar (34 times).\n\n" +
                        "[Total = Exactly 100 Glorifications before sleeping]",
                translation = "Glory be to Allah (33 times),\nPraise be to Allah (33 times),\nAllah is the Greatest (34 times).\n\n[Total: Exactly 100 tasbeeh recited upon retiring to bed]",
                translationHausa = "Tasbihin Dari (100) na Sayyidatina Fatima (RA):\n\n" +
                        "1. SUBHANALLAH (Tsarki ya tabbata ga Allah) - Sau 33\n" +
                        "2. ALHAMDULILLAH (Godiya ta tabbata ga Allah) - Sau 33\n" +
                        "3. ALLAHU AKBAR (Allah ne Mafi Girma) - Sau 34\n\n" +
                        "Jimilla: Daidai Tasbihi Dari (100) kafin mutum ya kwanta barci.",
                translationYoruba = "Tasbihi 100 tí Sayyidatina Fatima (RA): Subhānallāh (ẹmẹ 33), Alhamdulillāh (ẹmẹ 33), Allāhu Akbar (ẹmẹ 34). Àpapọ̀ jẹ́ 100 ṣáájú sísùn.",
                translationIgbo = "Tasbeeh 100 nke Fatima: Subhanallah (ugboro 33), Alhamdulillah (ugboro 33), Allahu Akbar (ugboro 34). Ngụkọta bụ 100 tupu ụra.",
                reference = "Ali (RA) ya ruwaito cewa Fatima (RA) ta zo wurin Annabi (ﷺ) tana neman mai taya ta aiki saboda wahalar nika da aikin gida. Sai Annabi (ﷺ) ya ce mata da Ali: 'Shin ba zan nuna muku abin da ya fi muku ma'aikaci alheri ba? Idan kuka zo kwanciya a shimfidarku, ku yi Tasbihi (Subhanallah) sau 33, ku yi Tahmidi (Alhamdulillah) sau 33, ku yi Takbiri (Allahu Akbar) sau 34; lallai wannan ya fi muku ma'aikaci alheri.' Ali (RA) ya ce: 'Ban taba barin yin su ba tun lokacin da na ji su daga Manzon Allah (ﷺ).' (Sahih Al-Bukhari no. 3705, 5361; Sahih Muslim no. 2727)."
            ),

            // 4. Tasbihi Dari (100 Tasbeeh): Subhanallahi wa Bihamdihi
            DuaEntity(
                id = 363,
                category = "Bedtime & Night Sunnah",
                title = "Tasbihi Dari (100 Tasbeeh): Subhanallahi wa Bihamdihi Sau 100",
                arabic = "سُبْحَانَ اللَّهِ وَبِحَمْدِهِ (١٠٠ مَرَّةً)",
                transliteration = "Subhanallahi wa bihamdihi (100 times).",
                translation = "Glory be to Allah and His is the praise (recited 100 times before sleeping or daily).",
                translationHausa = "Tsarki ya tabbata ga Allah tare da yabonSa (sau 100 kafin barci ko a kowane yini).\n\nFalala: Manzon Allah (ﷺ) ya ce: 'Wanda ya ce: Subhanallahi wa bihamdihi sau dari (100) a rana guda, an kankare masa zunubansa koda kuwa sun kai yawan kumfar teku.'",
                translationYoruba = "Mímọ́ ni fún Allāhu pẹ̀lú ọpẹ́ Rẹ̀ (ẹmẹ 100). Gbogbo ẹ̀ṣẹ̀ ni a ó dáríjì bí ó tilẹ̀ pọ̀ bí ìfòfó omi òkun.",
                translationIgbo = "Otuto dịrị Chineke na ekele Ya (ugboro 100). A na-agbaghara mmehie niile ọbụlagodi na ha ruru ụfụfụ nke osimiri.",
                reference = "Sahih Al-Bukhari no. 6405; Sahih Muslim no. 2691."
            ),

            // 5. Tasbihi Dari (100 Tasbeeh): Tahlili Sau 100
            DuaEntity(
                id = 364,
                category = "Bedtime & Night Sunnah",
                title = "Tasbihi Dari (100 Tasbeeh): Tahlili Sau 100 Kariyar Shaidan",
                arabic = "لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ (١٠٠ مَرَّةً)",
                transliteration = "La ilaha illallahu wahdahu la sharika lahu, lahul-mulku wa lahul-hamdu, wa Huwa 'ala kulli shay'in Qadeer (100 times).",
                translation = "None has the right to be worshipped except Allah alone, without partner. To Him belongs all sovereignty and praise, and He is over all things omnipotent (recited 100 times).",
                translationHausa = "Babu abin bautawa da gaskiya sai Allah Shi kadai, ba Shi da abokin tarayya. Mulki da godiya NaSa ne, kuma Shi Mai ikon yi ne a kan komai (sau 100).\n\nFalala: Manzon Allah (ﷺ) ya ce: 'Wanda ya fadi wannan sau 100, ya yi daidai da ya 'yanta bayi goma (10), za a rubuta masa lada 100, a shafe masa zunubai 100, kuma ya zama garkuwa a gare shi daga Shaidan har dare ya yi.'",
                translationYoruba = "Kò sí ọlọ́hun mìíràn àfi Allāhu nìkan, kò ní orogún. TiRẹ̀ ni ìjọba àti gbogbo ọpẹ́ (ẹmẹ 100). Ó dọ́gba mọ́ ìtúsílẹ̀ ẹrú mẹ́wàá.",
                translationIgbo = "Ọ dịghị chi ọzọ ma ọ bụghị Chineke naanị Ya (ugboro 100). Ọ na-eweta nchebe pụọ n'aka ekwensu.",
                reference = "Sahih Al-Bukhari no. 3293; Sahih Muslim no. 2691."
            ),

            // 6. Ayat al-Kursi (Kariyar Dindindin Daga Shaidan)
            DuaEntity(
                id = 365,
                category = "Bedtime & Night Sunnah",
                title = "Ayat al-Kursi: Kariyar Dindindin Daga Shaidan Har Gari Ya Waye",
                arabic = "اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ",
                transliteration = "Allahu la ilaha illa Huwal-Hayyul-Qayyum, la ta'khudhuhu sinatun wa la nawm, lahu ma fis-samawati wa ma fil-ard, man dhal-ladhi yashfa'u 'indahu illa bi-idhnih, ya'lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bi-shay'im-min 'ilmihi illa bima sha'a, wasi'a kursiyyuhus-samawati wal-ard, wa la ya'uduhu hifzuhuma, wa Huwal-'Aliyyul-'Azim.",
                translation = "Allah - there is no deity except Him, the Ever-Living, the Sustainer of all existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.",
                translationHausa = "Allah, babu abin bautawa da gaskiya sai Shi, Mai Rai, Mai Kula da kowace halitta. Gyangyadi ba ya kama Shi ballantana barci. NaSa ne duk abin da ke cikin sammai da abin da ke cikin kasa. Wane ne zai iya yin ceto a wurinSa sai da izininSa? Yana sane da abin da ke gabaninsu da abin da ke bayansu, kuma ba su san komai daga iliminSa ba sai abin da Ya so. KursiyyunSa ya yalwaci sammai da kasa, kuma kiyaye su ba ya gajiyar da Shi, kuma Shi ne Maɗaukaki, Mai Girma.\n\nFalala: Manzon Allah (ﷺ) ya ce: 'Idan ka karanta Ayat al-Kursi lokacin da za ka kwanta barci, wani mai tsaro daga Allah zai ci gaba da zama tare da kai, kuma babu wani Shaidan da zai kusance ka har sai gari ya waye.'",
                translationYoruba = "Ayat al-Kursi: Ẹnikẹ́ni tí ó bá kà á ṣáájú sísùn, olùṣọ́ láti ọ̀dọ̀ Allāhu yóò wà pẹ̀lú rẹ̀, èṣù kankan kò sì ní súnmọ́ ọn títí di owurọ̀.",
                translationIgbo = "Ayat al-Kursi: Onye ọ bụla gụrụ ya tupu ọ lakpuo ụra, onye nche sitere n'aka Chineke ga-anọnyere ya, ọ dịghịkwa ekwensu ga-abịaru ya nso ruo ụtụtụ.",
                reference = "Surah Al-Baqarah 2:255; Sahih Al-Bukhari no. 2311 (Hadith Abu Hurairah tare da Shaidan)."
            ),

            // 7. Karshen Suratul Baqarah (Ayoyi Biyu Masu Isarwa)
            DuaEntity(
                id = 366,
                category = "Bedtime & Night Sunnah",
                title = "Karshen Suratul Baqarah (Amanar-Rasul - Ayoyi 285-286 Masu Isarwa)",
                arabic = "آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ﴿٢٨٦﴾",
                transliteration = "Amanar-Rasulu bima unzila ilayhi mir-Rabbihi wal-mu'minun, kullun amana billahi wa mala'ikatihi wa kutubihi wa rusulih, la nufarriqu bayna ahadim-mir-rusulih, wa qalu sami'na wa ata'na ghufranaka Rabbana wa ilaykal-maseer. [285] La yukallifullahu nafsan illa wus'aha, laha ma kasabat wa 'alayha maktasabat, Rabbana la tu'akhidhna in naseena aw akhta'na, Rabbana wa la tahmil 'alayna isran kama hamaltahu 'alalladhina min qablina, Rabbana wa la tuhammilna ma la taqata lana bih, wa'fu 'anna waghfir lana warhamna, Anta Mawlana fansurna 'alal-qawmil-kafirin. [286]",
                translation = "The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], 'We make no distinction between any of His messengers.' And they say, 'We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the final destination.' [285] Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. 'Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.' [286]",
                translationHausa = "Manzo ya yi imani da abin da aka saukar gare shi daga Ubangijinsa, da muminai; dukansu sun yi imani da Allah da Mala'ikunSa da LittattafanSa da ManzanninSa, suna cewa: 'Ba ma bambanta tsakanin kowa daga ManzanninSa.' Kuma suka ce: 'Mun ji kuma mun yi biyayya, muna neman gafararKa ya Ubangijinmu, kuma makoma gare Ka take.' [285] Allah ba Ya dorawa rai wani nauyi sai gwargwadon ikonta; tana da ladan abin da ta aikata na alheri, kuma tana da alhakin abin da ta aikata na sharri. 'Ya Ubangijinmu! Kada Ka kama mu da laifi idan mun manta ko mun yi kuskure. Ya Ubangijinmu! Kada Ka dora mana kaya mai nauyi kamar yadda Ka dora shi a kan wadanda suka gabace mu. Ya Ubangijinmu! Kada Ka dora mana abin da ba mu da ikon dauka. Ka yafe mana, Ka gafarta mana, kuma Ka yi mana rahama; Kai ne Majibinmu, Ka taimake mu a kan mutane kafirai.' [286]\n\nFalala: Manzon Allah (ﷺ) ya ce: 'Wanda ya karanta ayoyi biyu na karshen Suratul Baqarah a cikin dare, sun isar masa (daga kowane irin sharri, fitina ko cuta).' (Bukhari & Muslim).",
                translationYoruba = "Ẹnikẹ́ni tí ó bá ka àwọn ẹsẹ méjì ìkẹyìn Suratul Baqarah ní alẹ́, wọ́n tó fún un (lọ́wọ́ gbogbo aburú).",
                translationIgbo = "Onye ọ bụla gụrụ amaokwu abụọ ikpeazụ nke Suratul Baqarah n'abalị, ha zuru ya maka ihe ọjọọ niile.",
                reference = "Surah Al-Baqarah 2:285-286; Sahih Al-Bukhari no. 5009; Sahih Muslim no. 808."
            ),

            // 8. Tozarta Hannaye da Shafa Jiki: Kulhuwa, Falaqi da Nasi (Sau 3)
            DuaEntity(
                id = 367,
                category = "Bedtime & Night Sunnah",
                title = "Tozarta Hannaye da Shafa Jiki: Kulhuwa, Falaqi da Nasi (Sau 3)",
                arabic = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\n" +
                        "قُلْ هُوَ اللَّهُ أَحَدٌ ﴿١﴾ اللَّهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ﴿٤﴾\n\n" +
                        "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\n" +
                        "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾\n\n" +
                        "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\n" +
                        "قُلْ أَعُوذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَٰهِ النَّاسِ ﴿٣﴾ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾\n\n" +
                        "[تُقْرَأُ مَعَ النَّفْثِ فِي الْكَفَّيْنِ وَمَسْحِ الْجَسَدِ ثَلَاثَ مَرَّاتٍ]",
                transliteration = "Qul Huwallahu Ahad, Allahus-Samad, lam yalid wa lam yulad, wa lam yakun lahu kufuwan ahad. (Surah Al-Ikhlas)\n\n" +
                        "Qul a'udhu bi-Rabbil-falaq, min sharri ma khalaq, wa min sharri ghasiqin idha waqab, wa min sharrin-naffathati fil-'uqad, wa min sharri hasidin idha hasad. (Surah Al-Falaq)\n\n" +
                        "Qul a'udhu bi-Rabbin-nas, Malikin-nas, Ilahin-nas, min sharril-waswasil-khannas, alladhi yuwaswisu fee sudurin-nas, minal-jinnati wan-nas. (Surah An-Nas)\n\n" +
                        "[Blowing lightly into both cupped hands and wiping the head, face and body, repeated 3 times].",
                translation = "Recitation of Surah Al-Ikhlas, Surah Al-Falaq, and Surah An-Nas into cupped hands, blowing lightly into them, and wiping over the body starting with the head and face, repeated three times before sleeping.",
                translationHausa = "Sunnar Shafa Jiki da Surori Masu Neman Kariya:\n" +
                        "Manzon Allah (ﷺ) ya kasance a duk lokacin da zai kwanta a shimfidarsa a kowane dare, yana hada tafukan hannayensa biyu ya tofa a cikinsu (tofi mara yawu mai iska) sannan ya karanta: Qul Huwallahu Ahad, da Qul A'udhu bi-Rabbil-Falaq, da Qul A'udhu bi-Rabbin-Nas. Sannan ya shafi duk abin da zai iya shafa na jikinsa da tafukan hannayensa, yana farawa daga kansa da fuskarsa da kuma gaban jikinsa. Yana yin hakan sau uku (3).",
                translationYoruba = "Kíkà Kúlhuwa, Fálakì ati Nási sínú àtẹ́lẹwọ́ méjèèjì, fẹ́ afẹ́fẹ́ sí i, kí o sì fi pa gbogbo ara rẹ bẹ̀rẹ̀ láti orí àti ojú, ní ẹ̀mẹ́ta ṣáájú sísùn.",
                translationIgbo = "Ịgụ Al-Ikhlas, Al-Falaq na An-Nas n'ọbụ aka abụọ, na-eku ume nwayọọ na ya, ma na-ete ya n'ahụ niile malite n'isi na ihu, ugboro 3.",
                reference = "Sahih Al-Bukhari no. 5017; Sahih Muslim no. 2192 (Hadith Sayyidatina A'isha RA)."
            ),

            // 9. Bismika Rabbi Wada'tu Janbi
            DuaEntity(
                id = 368,
                category = "Bedtime & Night Sunnah",
                title = "Bismika Rabbi Wada'tu Janbi (Mika Wuya ga Kaddarar Rai)",
                arabic = "بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ",
                transliteration = "Bismika Rabbi wada'tu janbi, wa bika arfa'uh, fa-in amsakta nafsi far-hamha, wa in arsaltaha fah-fazha bima tahfazu bihi 'ibadakas-salihin.",
                translation = "In Your name my Lord, I lie down and in Your name I rise, so if You should take my soul then have mercy upon it, and if You should return my soul then protect it in the manner You do so with Your righteous servants.",
                translationHausa = "Da sunanKa ya Ubangijina na kwantar da gefena, kuma da ikonKa nake dago shi. Idan Ka rike raina (a cikin barcin) Ka yi masa rahama, idan kuma Ka sake shi (zuwa wayewar gari) Ka kare shi da abin da Kake kare bayinKa salihai da shi.",
                translationYoruba = "Pẹ̀lú orúkọ Rẹ Olúwa mi ni mo fi gbé ẹ̀gbẹ́ mi lélẹ̀, pẹ̀lú Rẹ ni mo sì n gbé e dìde. Bí O bá mú ẹ̀mí mi, ṣàánú fún un; bí O bá sì dá a padà, ṣọ́ ọ pẹ̀lú ohun tí O fi n ṣọ́ àwọn ẹrú Rẹ olódodo.",
                translationIgbo = "N'aha Gị Onyenwe m ka m dabere, n'aha Gị ka m ga-ebili. Ọ bụrụ na Ị nara mkpụrụ obi m, meere ya ebere; ọ bụrụ na Ị hapụ ya, chebe ya dịka Ị na-echebe ndị ohu Gị ezi omume.",
                reference = "Sahih Al-Bukhari no. 6320; Sahih Muslim no. 2714 (Hadith Abu Hurairah RA)."
            ),

            // 10. Allahumma Aslamtu Nafsi Ilayk (Kalmar Karshe Kafin Barci a kan Fitrah)
            DuaEntity(
                id = 369,
                category = "Bedtime & Night Sunnah",
                title = "Allahumma Aslamtu Nafsi Ilayk (Addu'ar Kwanciya ta Karshe a kan Fitrah)",
                arabic = "اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ",
                transliteration = "Allahumma aslamtu nafsi ilayk, wa fawwadtu amri ilayk, wa wajjahtu wajhi ilayk, wa alja'tu zahri ilayk, raghbatan wa rahbatan ilayk, la malja'a wa la manja minka illa ilayk, amantu bi-kitabikal-ladhi anzalta, wa bi-nabiyyikal-ladhi arsalt.",
                translation = "O Allah, I submit myself to You, entrust my affair to You, turn my face towards You, and put my trust in You, in hope and in fear of You. There is no refuge and no escape from You except to You. I believe in Your Book which You have revealed and in Your Prophet whom You have sent.",
                translationHausa = "Ya Allah, na mika kaina gare Ka, kuma na wakilta al'amarina gare Ka, kuma na juya fuskata gare Ka, kuma na jingina bayana gare Ka, don kwadayin samun ladanKa da tsoron azabarKa; babu mafaka babu mafita daga gare Ka face zuwa gare Ka. Na yi imani da LittafinKa da Ka saukar, da kuma AnnabinKa da Ka aiko.\n\nFalala: Manzon Allah (ﷺ) ya ce wa Al-Bara' bin 'Azib: 'Idan ka karanta wannan addu'ar kafin barci, ka mayar da ita kalmarka ta karshe; idan ka mutu a wannan daren, ka mutu a kan dabi'ar Musulunci (Fitrah).'",
                translationYoruba = "Allāhu, mo ju ara mi sílẹ̀ fún Ọ, mo fi ọ̀rọ̀ mi lé Ọ lọ́wọ́. Bí o bá kú ní alẹ́ náà, o kú lórí ẹ̀sìn tòótọ́ (Fitrah).",
                translationIgbo = "Chineke, enyefere m onwe m n'aka Gị. Ọ bụrụ na ị nwụọ n'abalị ahụ, ị nwụrụ n'okwukwe ziri ezi.",
                reference = "Sahih Al-Bukhari no. 247, 6311; Sahih Muslim no. 2710."
            ),

            // 11. Allahumma Qini 'Adhabaka (Sau 3)
            DuaEntity(
                id = 370,
                category = "Bedtime & Night Sunnah",
                title = "Allahumma Qini 'Adhabaka: Kariya Daga Azaba (Sau 3 da Tafin Hannu a Kunci)",
                arabic = "اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ (ثَلَاثَ مَرَّاتٍ)",
                transliteration = "Allahumma qini 'adhabaka yawma tab'athu 'ibadak (3 times).",
                translation = "O Allah, protect me from Your punishment on the Day You resurrect Your servants (recited 3 times with right hand placed under the cheek).",
                translationHausa = "Ya Allah Ka kare ni daga azabarKa a ranar da Zaka tayar da bayinKa (ana karanta ta sau uku tare da sanya tafin hannun dama a karkashin kuncin dama).",
                translationYoruba = "Allāhu, gbà mí lọ́wọ́ ìyà Rẹ ní ọjọ́ tí O ó jí àwọn ẹrú Rẹ dìde (ẹmẹ mẹ́ta).",
                translationIgbo = "Chineke, chebe m pụọ n'ahụhụ Gị n'ụbọchị Ị ga-akpọlite ndị ohu Gị n'ọnwụ (ugboro 3).",
                reference = "Sunan Abu Dawud no. 5045; Jami' At-Tirmidhi no. 3398 (Sahih). Annabi (ﷺ) ya kasance yana sanya hannunsa na dama a karkashin kuncinsa na dama sannan ya fadi wannan addu'a sau uku."
            ),

            // 12. Godiya ga Allah a kan Ni'imar Abinci, Ruwa da Gurbin Kwana
            DuaEntity(
                id = 371,
                category = "Bedtime & Night Sunnah",
                title = "Godiya ga Allah a kan Ni'imar Abinci, Ruwa da Gurbin Kwana",
                arabic = "الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ",
                transliteration = "Alhamdu lillahil-ladhi at'amana wa saqana, wa kafana wa awana, fakam mimman la kafiya lahu wa la mu'wiya.",
                translation = "Praise is to Allah Who has provided us with food and with drink, sufficed us and gave us an abode, for how many are there who have no one to suffice them and no one to provide them shelter.",
                translationHausa = "Dukkan godiya ta tabbata ga Allah Wanda Ya ciyar da mu, Ya shayar da mu, Ya isar mana (wajen bukatunmu), kuma Ya ba mu masauki (wajen kwana); domin kuwa da yawa daga mutane babu mai isar musu kuma babu mai ba su masauki.",
                translationYoruba = "Ọpẹ́ ni fún Allāhu tí Ó bọ́ wa, tí Ó fún wa ní omi mu, tí Ó tó wa, tí Ó sì fún wa ní ibùgbé; mélòó nínú àwọn ènìyàn ni kò ní ẹni tí ó tó wọn tàbí fún wọn ní ibùgbé.",
                translationIgbo = "Otuto dịrị Chineke Onye nyere anyị nri na ihe ọṅụṅụ, ma nye anyị ebe obibi.",
                reference = "Sahih Muslim no. 2715 (Hadith Anas bin Malik RA)."
            ),

            // 13. Addu'ar Neman Kariya Daga Dukkan Sharrin Halittu da Biyan Bashi
            DuaEntity(
                id = 372,
                category = "Bedtime & Night Sunnah",
                title = "Addu'ar Neman Kariya Daga Sharrin Kowane Mai Sharri da Biyan Bashi",
                arabic = "اللَّهُمَّ رَبَّ السَّمَاوَاتِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ",
                transliteration = "Allahumma Rabbas-samawati wa Rabbal-ardi wa Rabbal-'Arshil-'Azim, Rabbana wa Rabba kulli shay', faliqal-habbi wan-nawa, wa munzilat-Tawrati wal-Injeeli wal-Furqan, a'udhu bika min sharri kulli shay'in Anta akhidhun bi-nasiyatih. Allahumma Antal-Awwalu fa-laysa qablaka shay', wa Antal-Akhiru fa-laysa ba'daka shay', wa Antaz-Zahiru fa-laysa fawqaka shay', wa Antal-Batinu fa-laysa dunaka shay', iqdi 'annad-dayna wa aghnina minal-faqr.",
                translation = "O Allah, Lord of the heavens and Lord of the earth and Lord of the Mighty Throne, our Lord and Lord of everything, Cleaver of the seed and kernel, and Revealer of the Torah, the Gospel, and the Criterion. I seek refuge in You from the evil of everything You have control over. O Allah, You are the First and there is nothing before You, and You are the Last and there is nothing after You, and You are the Manifest and there is nothing above You, and You are the Hidden and there is nothing beyond You. Settle our debts and enrich us from poverty.",
                translationHausa = "Ya Allah, Ubangijin sammai da Ubangijin kasa da Ubangijin Al'arshi Mai Girma, Ubangijinmu kuma Ubangijin kowane abu, Mai tsaga kwaya da kwallon dabino, Mai saukar da Attaura da Linjila da Alkur'ani Mai Raba Karya da Gaskiya. Ina neman tsari da Kai daga sharrin kowane abu da Kake rike da makwarkwadar kansa. Ya Allah, Kai ne Na Farko babu komai gabaninKa, kuma Kai ne Na Karshe babu komai bayanKa, kuma Kai ne Mabayyani babu abin da ke samanKa, kuma Kai ne Boyayye babu abin da ya buya gare Ka; Ka biya mana bashinmu kuma Ka wadatar da mu daga talauci.",
                translationYoruba = "Allāhu, Olúwa àwọn ọ̀run àti ayé, san gbogbo gbèsè wa fún wa, kí O sì sọ wá di ọlọ́rọ̀ kúrò nínú ipò tálákà.",
                translationIgbo = "Chineke, Onyenwe eluigwe na ala, kwụọ ụgwọ anyị ma mee anyị ndị nwere akụ na ụba pụọ na ịda ogbenye.",
                reference = "Sahih Muslim no. 2713 (Hadith Abu Hurairah RA)."
            ),

            // 14. Addu'ar Kakkabe Shimfida Sau Uku (Sunnar Dusting the Bed)
            DuaEntity(
                id = 373,
                category = "Bedtime & Night Sunnah",
                title = "Addu'ar Kakkabe Shimfida Sau Uku Kafin Kwanciya",
                arabic = "بِسْمِ اللَّهِ.. «إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ إِزَارِهِ، فَإِنَّهُ لَا يَدْرِي مَا خَلَفَهُ عَلَيْهِ، ثُمَّ يَقُولُ: بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ...»",
                transliteration = "Bismillah.. 'Idha awa ahadukum ila firashihi fal-yanfud firashahu bi-dakhilati izarihi fa-innahu la yadri ma khalafahu 'alayh, thumma yaqulu: Bismika Rabbi wada'tu janbi wa bika arfa'uh...'",
                translation = "In the name of Allah.. 'When one of you goes to his bed, let him dust his bed with the edge of his lower garment, for he does not know what took his place on it after he left, then let him say: In Your Name my Lord I lie down...'",
                translationHausa = "Sunnar Kakkabe Shimfida:\nManzon Allah (ﷺ) ya ce: 'Idan dayanku ya zo shimfidarsa domin ya kwanta, to ya kakkabe shimfidarsa da gefen mayafinsa ko zannensa sau uku (3), domin bai san abin da ya shiga ciki bayan ya tashi ba (kamar kwari, kunama ko datti), sannan ya karanta Bismillah da addu'ar kwanciya.'",
                translationYoruba = "Gbọ́n ibùsùn rẹ ní ẹ̀mẹ́ta pẹ̀lú Bismillāh ṣáájú kí o tó dùbúlẹ̀, nítorí o kò mọ ohun tí ó wọ̀ ọ́ lẹ́yìn rẹ.",
                translationIgbo = "Kpochapụ ihe ndina gị ugboro atọ na Bismillah tupu ị lakpuo.",
                reference = "Sahih Al-Bukhari no. 6320; Sahih Muslim no. 2714."
            ),

            // 15. Addu'ar Wanda Ya Tashi Cikin Dare ko Ya Juya
            DuaEntity(
                id = 374,
                category = "Bedtime & Night Sunnah",
                title = "Addu'ar Wanda Ya Farka Cikin Dare ko Yake Juyawa a Shimfida",
                arabic = "لَا إِلَهَ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ",
                transliteration = "La ilaha illallahul-Wahidul-Qahhar, Rabbus-samawati wal-ardi wa ma baynahumal-'Azizul-Ghaffar.",
                translation = "There is no god except Allah, the One, the Subduer, Lord of the heavens and the earth and whatever is between them, the Exalted in Might, the Perpetual Forgiver.",
                translationHausa = "Babu abin bautawa da gaskiya sai Allah Makaɗaici, Mai Rinjaye a kan kowa, Ubangijin sammai da kasa da abin da ke tsakaninsu, Mabuwayi, Mai yawan gafara.\n\nFalala: Sayyidatina A'isha (RA) ta ruwaito cewa Manzon Allah (ﷺ) ya kasance a duk lokacin da ya juya a shimfidarsa da daddare yana karanta wannan addu'ar.",
                translationYoruba = "Kò sí ọlọ́hun mìíràn àfi Allāhu Ọ̀kan ṣoṣo, Alágbára, Olúwa àwọn ọ̀run àti ayé àti ohun tí ó wà láàárín wọn, Alágbára, Olùdáríjì.",
                translationIgbo = "Ọ dịghị chi ọzọ ma ọ bụghị Chineke, Onye Na-achị ihe niile, Onyenwe eluigwe na ala na ihe dị n'etiti ha.",
                reference = "Sunan An-Nasa'i; Al-Hakim (1/540); Sahih Al-Jami' As-Saghir no. 4693."
            ),

            // 16. Addu'ar Firgita ko Tsoro Yayin Barci
            DuaEntity(
                id = 375,
                category = "Bedtime & Night Sunnah",
                title = "Addu'ar Firgita ko Tsoro Yayin Barci da Mafarki Mai Muni",
                arabic = "أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ",
                transliteration = "A'udhu bi-kalimatillahit-tammati min ghadabihi wa 'iqabihi, wa sharri 'ibadihi, wa min hamazatish-shayatini wa an yahduroon.",
                translation = "I seek refuge in the perfect words of Allah from His anger and His punishment, from the evil of His slaves, and from the whisperings and incitements of devils and from their presence.",
                translationHausa = "Ina neman tsari da cikakkun kalmomin Allah daga fushinSa da azabarSa, da sharrin bayinSa, da kuma zuga da waswasi na shaidanu da kuma kada su halarce ni.",
                translationYoruba = "Mo wa isadi pẹlu awọn ọrọ Allāhu ti o pe perepere kuro ninu ibinu Rẹ ati iya Rẹ, ati aburu awọn ẹru Rẹ, ati idamu eṣu.",
                translationIgbo = "Ana m achọ ebe mgbaba n'okwu zuru oke nke Chineke pụọ n'iwe Ya na ntaramahụhụ Ya, na ihe ọjọọ nke ndị ohu Ya.",
                reference = "Sunan Abu Dawud no. 3893; Jami' At-Tirmidhi no. 3528 (Hasan)."
            ),

            // 17. Hukunci da Sunnar Mafarki (Mai Kyau ko Mara Kyau)
            DuaEntity(
                id = 376,
                category = "Bedtime & Night Sunnah",
                title = "Hukunci da Hanyar Sunnah Idan Anyi Mafarki Mai Kyau ko Mara Kyau",
                arabic = "قَالَ ﷺ: «الرُّؤْيَا الصَّالِحَةُ مِنَ اللَّهِ، وَالْحُلُمُ مِنَ الشَّيْطَانِ، فَمَنْ رَأَى شَيْئًا يَكْرَهُهُ فَلْيَنْفُثْ عَنْ شِمَالِهِ ثَلَاثًا، وَلْيَتَعَوَّذْ بِاللَّهِ مِنَ الشَّيْطَانِ ثَلَاثًا، وَلَا يُحَدِّثْ بِهَا أَحَدًا، فَإِنَّهَا لَنْ تَضُرَّهُ، وَلْيَتَحَوَّلْ عَنْ جَنْبِهِ الَّذِي كَانَ عَلَيْهِ»",
                transliteration = "Qala (SAW): 'Ar-ru'yas-salihah minallah, wal-hulumu minash-shaytan, fa-man ra'a shay'an yakrahuhu fal-yanfuth 'an shimalihi thalatha, wal-yata'awwadh billahi minash-shaytani thalatha, wa la yuhaddith biha ahada, fa-innaha lan tadurrah, wal-yatahawwal 'an janbihil-ladhi kana 'alayh.'",
                translation = "The Prophet (ﷺ) said: 'A good dream is from Allah, and a bad dream is from Satan. So whoever sees something he dislikes, let him spit dryly to his left three times, seek refuge with Allah from Satan three times, not mention it to anyone, and it will not harm him; and let him turn over from the side he was sleeping on.'",
                translationHausa = "Hukuncin Sunnah Yayin Mafarki:\n" +
                        "1. Mafarki Mai Kyau: Daga Allah yake; mutum ya gode wa Allah (Alhamdulillah) kuma kada ya fada wa kowa sai wanda yake so kuma yake kaunarsa.\n" +
                        "2. Mafarki Mara Kyau: Daga Shaidan yake; mutum ya yi tofi mara yawu a bangarensa na hagu sau uku (3), ya nemi tsarin Allah daga Shaidan sau uku (A'udhu billahi minash-shaytanir-rajim), kada ya fada wa kowa wannan mafarkin, ya juya zuwa daya gefen na kwanciya, kuma idan yana so zai iya tashi ya yi sallah raka'a biyu. Idan ya yi haka, mafarkin ba zai cutar da shi ba ko kadan.",
                translationYoruba = "Àlá rere wá láti ọ̀dọ̀ Allāhu, àlá búburú sì wá láti ọ̀dọ̀ èṣù. Bí o bá rí àlá búburú, fẹ́ itọ́ sí apá òsì rẹ ní ẹ̀mẹ́ta, bẹ Allāhu fún ààbò, má ṣe sọ fún ẹnìkan, kò sì ní pa ọ́ lára.",
                translationIgbo = "Ezi nrọ sitere n'aka Chineke, nrọ ọjọọ sitere n'aka ekwensu. Ọ bụrụ na ị hụ nrọ ọjọọ, gbụọ asụ n'aka ekpe ugboro 3, rịọ Chineke maka nchebe, agwala onye ọ bụla, ọ gaghị emerụ gị ahụ.",
                reference = "Sahih Al-Bukhari no. 6984, 7044; Sahih Muslim no. 2261."
            ),

            // 18. Suratus-Sajdah Kafin Barci
            DuaEntity(
                id = 377,
                category = "Bedtime & Night Sunnah",
                title = "Suratus-Sajdah Kafin Barci (Hadithin Manzon Allah ﷺ)",
                arabic = "عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: «أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَنَامُ حَتَّى يَقْرَأَ: الم تَنْزِيلُ (السَّجْدَةَ)، وَتَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ»\n\nبِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\nالم ﴿١﴾ تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ ﴿٢﴾ أَمْ يَقُولُونَ افْتَرَاهُ ۚ بَلْ هُوَ الْحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ ﴿٣﴾ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ ۖ مَا لَكُم مِّن دُونِهِ مِن وَلِيٍّ وَلَا شَفِيعٍ ۚ أَفَلَا تَتَذَكَّرُونَ ﴿٤﴾",
                transliteration = "Jabir (RA) narrated: 'The Prophet (ﷺ) would not go to sleep until he recited Alif-Lam-Mim Tanzil (Suratus-Sajdah) and Tabarakalladhi bi-yadihil-Mulk (Surah Al-Mulk).'\n\nBismillahir-Rahmanir-Rahim. Alif-Lam-Meem. [1] Tanzeelul-Kitabi la rayba feehi mir-Rabbil-'alameen. [2] Am yaqulunafta-rah, bal huwal-haqqu mir-Rabbika li-tundhira qawmam-ma atahum min nadheerin min qablika la'allahum yahtadoon. [3] Allahulladhi khalaqas-samawati wal-arda wa ma baynahuma fee sittati ayyamin thummas-tawa 'alal-'arsh, ma lakum min doonihi min waliyyin wa la shafee', afala tatadhakkaroon. [4]",
                translation = "Jabir (RA) narrated that the Prophet (ﷺ) would not sleep until he had recited Surah As-Sajdah and Surah Al-Mulk. It is a highly recommended Sunnah to recite Surah As-Sajdah every night along with Surah Al-Mulk for immense protection and reward.",
                translationHausa = "Sayyidina Jabir (RA) ya ruwaito cewa: 'Lallai Annabi (ﷺ) ya kasance ba ya yin barci a kowane dare har sai ya karanta Suratus-Sajdah (Alif-Lam-Mim Tanzil) da kuma Suratul Mulk (Tabarakallazi bi-yadihil Mulk).'\n\nWannan yana nuna matukar muhimmancin karanta wadannan surori guda biyu a kowane dare kafin kwanciya barci.",
                translationYoruba = "Jabir (RA) sọ pe Anabi (ﷺ) kò kì í sùn títí tí yóò fi ka Suratus-Sajdah ati Suratul Mulk.",
                translationIgbo = "Jabir (RA) kọrọ na Onye Amụma (ﷺ) anaghị alakpu ụra ruo mgbe ọ gụchara Suratus-Sajdah na Suratul Mulk.",
                reference = "Jami' At-Tirmidhi no. 2892, 3404; Sunan Ad-Darimi no. 3411; Musnad Ahmad (Sahih Al-Albani)."
            ),

