                title = "Addu'ar Tashi Daga Barci (Godiya ga Wanda Ya Rayar Bayan Mutuwa)",
                arabic = "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ",
                transliteration = "Alhamdu lillahil-ladhi ahyana ba'da ma amatana wa ilayhin-nushoor.",
                translation = "All praise is for Allah Who gave us life after having taken it from us, and unto Him is the resurrection.",
                translationHausa = "Dukkan godiya ta tabbata ga Allah Wanda Ya rayar da mu bayan Ya kashe mu (ta hanyar barci), kuma zuwa gare Shi ne tashi yake.",
                translationYoruba = "Gbogbo ọpẹ́ ni fún Allāhu tí Ó sọ wá di alààyè lẹ́yìn tí Ó ti pa wá, ọ̀dọ̀ Rẹ̀ sì ni àjínde wà.",
                translationIgbo = "Otuto niile dịrị Chineke Onye mere anyị ka anyị dị ndụ mgbe O gbusịrị anyị, ọ bụkwa n'ebe Ọ nọ ka mbilite n'ọnwụ dị.",
                reference = "Sahih Al-Bukhari no. 6312, 6324; Sahih Muslim no. 2711 (Hadith Hudhaifah bin Al-Yaman RA)."
